#if SHADING_PATH_MOBILE
Near = NearM; End = EndM; Width = WidthM; Gamma = GammaM; R = saturate(R / max(KeepM, 0.01));
#endif
float T = Near + (End - Near) * pow(saturate(R), Gamma);
float k = saturate((T - D) / Width);
float n = frac(52.9829189 * frac(dot(Pix + 5.588238 * (float)View.StateFrameIndexMod8, float2(0.06711056, 0.00583715))));
return (k > n) ? 1.0 : 0.0;

#if SHADING_PATH_MOBILE
Near = NearM; End = EndM; Width = WidthM; Gamma = GammaM; CG = CGM; R = saturate(R / max(KeepM, 0.01));
#endif
float g = CG * saturate((D - Near) / max(End - Near, 1.0));
#if SHADING_PATH_MOBILE
g += CrownM * (1.0 - saturate((D - Near) / max(End - Near, 1.0)));
#endif
float T = Near + (End - Near) * pow(saturate(R), Gamma);
if (D > T + Width + 3000.0) { return -LP; }
return LP * float3(g, g, 0.35 * g);

